templates.template:
/* ============================================================
 * XenStaff - ACP badge library styling. Light-only (ACP), so
 * plain hex values rather than theme variables.
 * ============================================================ */

/* --- Badge list --- */
.xsStaffAdmin-badgeName { display: inline-flex; align-items: center; gap: 12px; min-width: 0; }
.xsStaffAdmin-badgeChip {
	width: 34px;
	height: 34px;
	flex: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	border-radius: 9px;
	color: #fff;
	font-size: 15px;
	box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .08);
	overflow: hidden;
}
.xsStaffAdmin-badgeChip-img { width: 100%; height: 100%; object-fit: cover; }
.xsStaffAdmin-badgeName-text { display: flex; flex-direction: column; line-height: 1.3; min-width: 0; }
.xsStaffAdmin-badgeName-title { font-weight: 700; }
.xsStaffAdmin-badgeName-desc { font-size: 12px; color: #6b7280; }

.xsStaffAdmin-swatch {
	display: inline-block;
	width: 18px;
	height: 18px;
	border-radius: 5px;
	box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .15);
	vertical-align: middle;
}

/* --- Edit form live preview --- */
.xsStaffAdmin-preview { display: inline-flex; align-items: center; gap: 16px; }
.xsStaffAdmin-preview-chip {
	width: 60px;
	height: 60px;
	flex: none;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	border-radius: 16px;
	color: #fff;
	font-size: 28px;
	box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .08), 0 10px 24px rgba(17, 24, 60, .14);
	overflow: hidden;
}
.xsStaffAdmin-preview-img { width: 100%; height: 100%; object-fit: cover; }
.xsStaffAdmin-preview-iconwrap { display: inline-flex; align-items: center; justify-content: center; line-height: 1; }
.xsStaffAdmin-preview-title { font-size: 18px; font-weight: 800; color: #1f2937; }

/* --- Color field (native picker swatch + synced hex) --- */
.xsStaffAdmin-colorField { display: inline-flex; align-items: center; gap: 10px; }
.xsStaffAdmin-colorSwatch {
	width: 44px;
	height: 38px;
	flex: none;
	padding: 0;
	border: 1px solid #ccd2da;
	border-radius: 8px;
	background: none;
	cursor: pointer;
	-webkit-appearance: none;
	appearance: none;
}
.xsStaffAdmin-colorSwatch::-webkit-color-swatch-wrapper { padding: 3px; }
.xsStaffAdmin-colorSwatch::-webkit-color-swatch { border: none; border-radius: 5px; }
.xsStaffAdmin-colorSwatch::-moz-color-swatch { border: none; border-radius: 5px; }
.xsStaffAdmin-colorHex { max-width: 160px; }

/* =============================================================================
 * XenStaff — native XF chrome + large vignette cards that FLIP to show details.
 * Front = big portrait. Back = member info / actions.
 * ============================================================================= */

@xsStaff-accent: @xf-linkColor;
@xsStaff-border: @xf-borderColor;
@xsStaff-online: #16a34a;
@xsStaff-busy: #e11d48;
@xsStaff-away: #d97706;

.xsStaff-page
{
	--xsStaff-accent: @xsStaff-accent;
	margin-bottom: @xf-elementSpacer;
	color: @xf-textColor;
}

/* Masthead — roster stage + live dock */
.xsStaff-masthead
{
	--xsStaff-mast-pad: 32px;
	position: relative;
	margin: 0 0 @xf-elementSpacer;
	border: 1px solid @xsStaff-border;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentBg;
	overflow: hidden;
	box-shadow: 0 22px 50px fade(#000, 8%);
}
.xsStaff-masthead-rail
{
	position: absolute;
	left: 0;
	top: 18px;
	bottom: 18px;
	width: 4px;
	border-radius: 0 4px 4px 0;
	background: linear-gradient(180deg, @xsStaff-accent 0%, fade(@xsStaff-accent, 15%) 100%);
	z-index: 2;
}
.xsStaff-masthead-bg
{
	position: absolute;
	inset: 0;
	pointer-events: none;
	overflow: hidden;
}
.xsStaff-masthead-wash
{
	position: absolute;
	inset: 0;
	background:
		radial-gradient(120% 80% at 100% 0%, fade(@xsStaff-accent, 14%) 0%, transparent 55%),
		radial-gradient(90% 70% at 0% 100%, fade(@xsStaff-online, 10%) 0%, transparent 50%),
		linear-gradient(180deg, @xf-contentAltBg 0%, @xf-contentBg 55%);
}
.xsStaff-masthead-orb
{
	position: absolute;
	border-radius: 50%;
	filter: blur(0);
}
.xsStaff-masthead-orb--a
{
	width: 340px;
	height: 340px;
	top: -160px;
	right: -80px;
	background: radial-gradient(circle, fade(@xsStaff-accent, 26%) 0%, fade(@xsStaff-accent, 0%) 68%);
	animation: xsStaff-orbFloat 9s ease-in-out infinite;
}
.xsStaff-masthead-orb--b
{
	width: 260px;
	height: 260px;
	bottom: -120px;
	left: 8%;
	background: radial-gradient(circle, fade(@xsStaff-online, 18%) 0%, fade(@xsStaff-online, 0%) 70%);
	animation: xsStaff-orbFloat 11s ease-in-out infinite reverse;
}
.xsStaff-masthead-orb--c
{
	width: 160px;
	height: 160px;
	top: 40%;
	left: 42%;
	background: radial-gradient(circle, fade(@xsStaff-accent, 12%) 0%, transparent 70%);
	opacity: .7;
}
@keyframes xsStaff-orbFloat
{
	0%, 100% { transform: translate3d(0, 0, 0) scale(1); }
	50% { transform: translate3d(-12px, 10px, 0) scale(1.05); }
}
.xsStaff-masthead-grid
{
	position: absolute;
	inset: 0;
	opacity: .22;
	background-image:
		linear-gradient(fade(#000, 10%) 1px, transparent 1px),
		linear-gradient(90deg, fade(#000, 10%) 1px, transparent 1px);
	background-size: 32px 32px;
	-webkit-mask-image: radial-gradient(ellipse at 80% 20%, #000 10%, transparent 70%);
	mask-image: radial-gradient(ellipse at 80% 20%, #000 10%, transparent 70%);
}
.xsStaff-masthead-beam
{
	position: absolute;
	top: -20%;
	right: 18%;
	width: 2px;
	height: 140%;
	background: linear-gradient(180deg, transparent 0%, fade(@xsStaff-accent, 45%) 40%, transparent 100%);
	transform: rotate(18deg);
	opacity: .55;
}
.xsStaff-masthead-sheen
{
	position: absolute;
	inset: 0;
	background: linear-gradient(115deg, transparent 35%, fade(#fff, 22%) 48%, transparent 60%);
	transform: translateX(-55%);
	animation: xsStaff-mastheadSheen 8s ease-in-out infinite;
}
@keyframes xsStaff-mastheadSheen
{
	0%, 58% { transform: translateX(-55%); opacity: 0; }
	68% { opacity: .85; }
	100% { transform: translateX(55%); opacity: 0; }
}
.xsStaff-masthead-noise
{
	position: absolute;
	inset: 0;
	opacity: .035;
	background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

.xsStaff-masthead-stage
{
	position: relative;
	z-index: 1;
	display: grid;
	grid-template-columns: minmax(0, 1.15fr) minmax(220px, .85fr);
	gap: 20px 36px;
	align-items: center;
	padding: var(--xsStaff-mast-pad) var(--xsStaff-mast-pad) 20px ~"calc(var(--xsStaff-mast-pad) + 4px)";
}
.xsStaff-masthead-copy { min-width: 0; }
.xsStaff-masthead-eyebrow
{
	display: inline-flex;
	align-items: center;
	gap: 8px;
	margin: 0 0 14px;
	padding: 6px 14px 6px 10px;
	border-radius: 999px;
	background: @xf-contentBg;
	border: 1px solid @xsStaff-border;
	color: @xf-textColorMuted;
	font-size: 11px;
	font-weight: @xf-fontWeightHeavy;
	letter-spacing: .1em;
	text-transform: uppercase;
	box-shadow: 0 8px 20px fade(#000, 4%);
}
.xsStaff-masthead-eyebrow-dot
{
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: @xsStaff-accent;
	box-shadow: 0 0 0 4px fade(@xsStaff-accent, 18%);
	animation: xsStaff-pulse 2.2s ease-out infinite;
}
.xsStaff-masthead-eyebrow .fa,
.xsStaff-masthead-eyebrow .fa--xf { color: @xsStaff-accent; }

.xsStaff-masthead-title
{
	position: relative;
	margin: 0 0 12px;
}
.xsStaff-masthead-title-text
{
	display: block;
	font-size: ~"clamp(2.1rem, 4.2vw, 3.2rem)";
	font-weight: @xf-fontWeightHeavy;
	line-height: 1.05;
	letter-spacing: -.035em;
	color: @xf-textColor;
}
.xsStaff-masthead-title-rule
{
	display: block;
	width: 72px;
	height: 4px;
	margin-top: 14px;
	border-radius: 999px;
	background: linear-gradient(90deg, @xsStaff-accent 0%, fade(@xsStaff-accent, 0%) 100%);
}
.xsStaff-masthead-subtitle
{
	margin: 0;
	max-width: 34em;
	font-size: ~"clamp(0.95rem, 1.4vw, 1.08rem)";
	line-height: 1.6;
	color: @xf-textColorMuted;
}
.xsStaff-masthead-meta
{
	display: flex;
	flex-wrap: wrap;
	gap: 10px;
	margin-top: 20px;
}
.xsStaff-masthead-chip
{
	display: inline-flex;
	align-items: center;
	gap: 8px;
	padding: 8px 14px 8px 8px;
	border-radius: 999px;
	background: @xf-contentBg;
	border: 1px solid @xsStaff-border;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	color: @xf-textColor;
	box-shadow: 0 10px 24px fade(#000, 6%);
}
.xsStaff-masthead-chip-ico
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 26px;
	height: 26px;
	border-radius: 50%;
	background: fade(@xsStaff-accent, 12%);
	color: @xsStaff-accent;
}
.xsStaff-masthead-chip--live
{
	border-color: fade(@xsStaff-online, 40%);
	background: fade(@xsStaff-online, 9%);
	color: @xsStaff-online;
	padding-left: 12px;
}
.xsStaff-masthead-chip--live strong
{
	color: @xsStaff-online;
	font-variant-numeric: tabular-nums;
}
.xsStaff-masthead-pulse
{
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: @xsStaff-online;
	box-shadow: 0 0 0 0 fade(@xsStaff-online, 55%);
	animation: xsStaff-pulse 1.8s ease-out infinite;
}
@keyframes xsStaff-pulse
{
	0% { box-shadow: 0 0 0 0 fade(@xsStaff-online, 50%); }
	70% { box-shadow: 0 0 0 9px fade(@xsStaff-online, 0%); }
	100% { box-shadow: 0 0 0 0 fade(@xsStaff-online, 0%); }
}

/* Roster composition */
.xsStaff-masthead-roster
{
	position: relative;
	min-height: 210px;
	display: flex;
	align-items: center;
	justify-content: center;
}
.xsStaff-masthead-watermark
{
	position: absolute;
	right: -6%;
	top: 50%;
	transform: translateY(-50%);
	font-size: ~"clamp(4.5rem, 9vw, 7rem)";
	font-weight: @xf-fontWeightHeavy;
	letter-spacing: -.04em;
	line-height: 1;
	color: @xf-textColor;
	opacity: .05;
	text-transform: uppercase;
	user-select: none;
	pointer-events: none;
	white-space: nowrap;
}
.xsStaff-masthead-ring
{
	position: absolute;
	width: 190px;
	height: 190px;
	border-radius: 50%;
	border: 1px dashed fade(@xsStaff-accent, 35%);
	animation: xsStaff-ringSpin 22s linear infinite;
}
.xsStaff-masthead-ring::before
{
	content: '';
	position: absolute;
	inset: 14px;
	border-radius: 50%;
	border: 1px solid fade(@xsStaff-accent, 16%);
}
@keyframes xsStaff-ringSpin
{
	to { transform: rotate(360deg); }
}
.xsStaff-masthead-faces
{
	position: relative;
	width: 220px;
	height: 200px;
}
.xsStaff-masthead-face
{
	position: absolute;
	z-index: ~"calc(10 - var(--xs-face, 0))";
	transition: transform .25s ease, z-index 0s;
	opacity: 0;
	animation: xsStaff-faceIn .65s ease forwards;
	animation-delay: ~"calc(var(--xs-face, 0) * 70ms)";
}
@keyframes xsStaff-faceIn
{
	from { opacity: 0; }
	to { opacity: 1; }
}
.xsStaff-masthead-face-frame
{
	display: block;
	border-radius: 50%;
	padding: 3px;
	background: linear-gradient(145deg, fade(@xsStaff-accent, 70%), fade(@xsStaff-accent, 10%));
	box-shadow: 0 14px 28px fade(#000, 18%);
}
.xsStaff-masthead-face .avatar,
.xsStaff-masthead-face .avatar img
{
	display: block;
	width: 54px !important;
	height: 54px !important;
	border-radius: 50% !important;
	border: 3px solid @xf-contentBg !important;
	box-sizing: border-box;
}
.xsStaff-masthead-face--lead
{
	left: 50%;
	top: 50%;
	transform: translate(-50%, -54%);
	z-index: 20;
}
.xsStaff-masthead-face--lead .xsStaff-masthead-face-frame
{
	border-radius: 22px;
	padding: 4px;
	background: linear-gradient(160deg, @xsStaff-accent, fade(@xsStaff-accent, 20%));
	box-shadow:
		0 0 0 6px fade(@xsStaff-accent, 10%),
		0 22px 40px fade(#000, 22%);
}
.xsStaff-masthead-face--lead .avatar,
.xsStaff-masthead-face--lead .avatar img
{
	width: 112px !important;
	height: 112px !important;
	border-radius: 18px !important;
	border-width: 4px !important;
}
.xsStaff-masthead-face--lead:hover { transform: translate(-50%, -58%) scale(1.03); }

.xsStaff-masthead-face:nth-child(2) { left: 8px; top: 18px; }
.xsStaff-masthead-face:nth-child(3) { right: 4px; top: 10px; }
.xsStaff-masthead-face:nth-child(4) { left: 0; bottom: 10px; }
.xsStaff-masthead-face:nth-child(5) { right: 2px; bottom: 18px; }

.xsStaff-masthead-face:not(.xsStaff-masthead-face--lead):hover
{
	transform: translateY(-6px) scale(1.06);
	z-index: 30;
}

.xsStaff-masthead-faceMore
{
	position: absolute;
	right: 28px;
	top: 50%;
	transform: translateY(-20%);
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 48px;
	height: 48px;
	border-radius: 50%;
	background: @xf-contentBg;
	border: 2px solid @xsStaff-border;
	color: @xf-textColor;
	font-size: @xf-fontSizeSmall;
	font-weight: @xf-fontWeightHeavy;
	box-shadow: 0 12px 24px fade(#000, 12%);
	z-index: 15;
}

/* Live stats dock */
.xsStaff-masthead-dock
{
	position: relative;
	z-index: 1;
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
	gap: 10px;
	margin: 0 16px 16px;
	padding: 0;
}
.xsStaff-masthead-stat
{
	position: relative;
	display: flex;
	align-items: center;
	gap: 12px;
	padding: 14px 14px 16px;
	min-width: 0;
	border: 1px solid @xsStaff-border;
	border-radius: 16px;
	background: @xf-contentAltBg;
	box-shadow: 0 10px 24px fade(#000, 5%);
	overflow: hidden;
	transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.xsStaff-masthead-stat:hover
{
	transform: translateY(-3px);
	border-color: fade(@xsStaff-accent, 35%);
	box-shadow: 0 16px 30px fade(#000, 8%);
}
.xsStaff-masthead-stat-icon
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 42px;
	height: 42px;
	border-radius: 13px;
	background: fade(@xsStaff-accent, 12%);
	color: @xsStaff-accent;
	font-size: 14px;
	flex: 0 0 auto;
}
.xsStaff-masthead-stat--online .xsStaff-masthead-stat-icon
{
	background: fade(@xsStaff-online, 14%);
	color: @xsStaff-online;
}
.xsStaff-masthead-stat--thanks .xsStaff-masthead-stat-icon
{
	background: fade(@xsStaff-busy, 12%);
	color: @xsStaff-busy;
}
.xsStaff-masthead-stat--speed .xsStaff-masthead-stat-icon
{
	background: fade(@xsStaff-away, 14%);
	color: @xsStaff-away;
}
.xsStaff-masthead-stat-body { min-width: 0; }
.xsStaff-masthead-stat-num
{
	font-size: 1.55rem;
	font-weight: @xf-fontWeightHeavy;
	line-height: 1.05;
	color: @xf-textColor;
	font-variant-numeric: tabular-nums;
	letter-spacing: -.02em;
}
.xsStaff-masthead-stat-unit
{
	font-size: @xf-fontSizeSmall;
	color: @xf-textColorMuted;
	margin-left: 2px;
	font-weight: @xf-fontWeightHeavy;
}
.xsStaff-masthead-stat-label
{
	margin-top: 3px;
	font-size: 10px;
	font-weight: @xf-fontWeightHeavy;
	color: @xf-textColorMuted;
	text-transform: uppercase;
	letter-spacing: .08em;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.xsStaff-masthead-stat-bar
{
	position: absolute;
	left: 14px;
	right: 14px;
	bottom: 0;
	height: 3px;
	border-radius: 999px 999px 0 0;
	background: linear-gradient(90deg, @xsStaff-accent, fade(@xsStaff-accent, 0%));
	opacity: .55;
}
.xsStaff-masthead-stat--online .xsStaff-masthead-stat-bar { background: linear-gradient(90deg, @xsStaff-online, fade(@xsStaff-online, 0%)); }
.xsStaff-masthead-stat--thanks .xsStaff-masthead-stat-bar { background: linear-gradient(90deg, @xsStaff-busy, fade(@xsStaff-busy, 0%)); }
.xsStaff-masthead-stat--speed .xsStaff-masthead-stat-bar { background: linear-gradient(90deg, @xsStaff-away, fade(@xsStaff-away, 0%)); }

.xsStaff-topHero
{
	position: relative;
	margin: 0 0 @xf-elementSpacer;
	max-width: 320px;
}
.xsStaff-topHero-ribbon
{
	position: absolute;
	top: 12px;
	left: 12px;
	z-index: 6;
	display: inline-flex;
	align-items: center;
	gap: 6px;
	padding: 4px 10px;
	border-radius: @xf-borderRadiusMedium;
	background: @xsStaff-accent;
	color: #fff;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
	text-transform: uppercase;
	letter-spacing: .06em;
	pointer-events: none;
}

.xsStaff-group { margin: 0 0 @xf-elementSpacer; }
.xsStaff-group-head
{
	display: flex;
	align-items: center;
	gap: 12px;
	margin: 0 0 @xf-paddingLarge;
}
.xsStaff-group-rule
{
	flex: 1;
	height: 1px;
	background: @xsStaff-border;
}
.xsStaff-group-title
{
	margin: 0;
	font-size: @xf-fontSizeLarge;
	font-weight: @xf-fontWeightHeavy;
	color: @xf-textColor;
	white-space: nowrap;
	background: none;
	-webkit-text-fill-color: currentColor;
	text-transform: none;
	letter-spacing: 0;
}
.xsStaff-group-count
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 22px;
	height: 22px;
	padding: 0 7px;
	border-radius: @xf-borderRadiusMedium;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	color: @xf-textColorMuted;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
}

.xsStaff-grid
{
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
	gap: @xf-paddingLarge;
}

/* =============================================================================
 * FLIP CARD
 * ============================================================================= */
.xsStaff-flip
{
	--xsStaff-accent: @xsStaff-accent;
	position: relative;
	height: 380px;
	perspective: 1400px;
	outline: none;
	cursor: pointer;
}
.xsStaff-flip--featured { height: 400px; }
.xsStaff-flip:focus-visible
{
	outline: 2px solid @xsStaff-accent;
	outline-offset: 3px;
	border-radius: @xf-borderRadiusLarge;
}

.xsStaff-flip-inner
{
	position: relative;
	width: 100%;
	height: 100%;
	transform-style: preserve-3d;
	transition: transform .55s cubic-bezier(.2, .8, .2, 1);
}

/* Desktop: hover flips to the info face */
@media (hover: hover) and (pointer: fine)
{
	.xsStaff-flip:hover .xsStaff-flip-inner,
	.xsStaff-flip:focus-within .xsStaff-flip-inner
	{
		transform: rotateY(180deg);
	}
	/* Soft lift + portrait zoom before / while approaching the flip */
	.xsStaff-flip:hover .xsStaff-card--front
	{
		box-shadow:
			0 18px 36px -18px fade(@xf-textColor, 35%),
			0 0 0 1px fade(@xsStaff-accent, 28%);
	}
	.xsStaff-flip:hover .xsStaff-card-vignette-media
	{
		transform: scale(1.05);
	}
	.xsStaff-flip:hover .xsStaff-card-vignette-sheen
	{
		opacity: 1;
		transform: translateX(120%) skewX(-18deg);
	}
}

/* Click / tap / keyboard lock */
.xsStaff-flip.is-flipped .xsStaff-flip-inner
{
	transform: rotateY(180deg);
}

.xsStaff-card-face
{
	position: absolute;
	inset: 0;
	-webkit-backface-visibility: hidden;
	backface-visibility: hidden;
	border-radius: @xf-borderRadiusLarge;
}
.xsStaff-card-face--front { transform: rotateY(0deg); z-index: 2; }
.xsStaff-card-face--back { transform: rotateY(180deg); z-index: 1; }

.xsStaff-card,
.xsStaff-card--front,
.xsStaff-card--back
{
	display: flex;
	flex-direction: column;
	height: 100%;
	margin: 0;
	padding: 0;
	border: 1px solid @xsStaff-border;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentBg;
	box-shadow: 0 2px 10px fade(@xf-textColor, 10%);
	overflow: hidden;
	color: @xf-textColor;
	transition: box-shadow .25s ease;
}
.xsStaff-flip--featured .xsStaff-card
{
	border-color: fade(@xsStaff-accent, 50%);
	box-shadow:
		0 2px 10px fade(@xf-textColor, 10%),
		0 0 0 1px fade(@xsStaff-accent, 18%);
}
.xsStaff-card::before { content: none; }
.xsStaff-card:hover { transform: none; }

/* FRONT vignette — cinematic portrait */
.xsStaff-card-vignette
{
	position: relative;
	flex: 1;
	min-height: 0;
	background: @xf-contentAltBg;
	overflow: hidden;
}
.xsStaff-card-vignette-media
{
	position: absolute;
	inset: 0;
	z-index: 0;
	transform: scale(1);
	transition: transform .55s cubic-bezier(.2, .8, .2, 1);
	will-change: transform;
}
.xsStaff-card-vignette .avatar,
.xsStaff-card-vignette .avatar img,
.xsStaff-card-vignette a.avatar
{
	display: block !important;
	position: absolute !important;
	inset: 0 !important;
	width: 100% !important;
	height: 100% !important;
	max-width: none !important;
	max-height: none !important;
	border-radius: 0 !important;
	border: 0 !important;
	box-shadow: none !important;
	object-fit: cover;
	object-position: center 20%;
}
.xsStaff-card-vignette .avatar > span,
.xsStaff-card-vignette .avatar.avatar--default--dynamic,
.xsStaff-card-vignette .avatar.avatar--default--text
{
	width: 100% !important;
	height: 100% !important;
	display: flex !important;
	align-items: center !important;
	justify-content: center !important;
	font-size: 88px !important;
	font-weight: @xf-fontWeightHeavy !important;
	letter-spacing: -.04em !important;
	border-radius: 0 !important;
	text-shadow: 0 8px 28px fade(#000, 25%);
}

/* Soft light sweep */
.xsStaff-card-vignette-sheen
{
	position: absolute;
	top: -20%;
	left: -40%;
	z-index: 2;
	width: 45%;
	height: 140%;
	pointer-events: none;
	opacity: 0;
	background: linear-gradient(
		90deg,
		transparent,
		fade(#fff, 18%),
		transparent
	);
	transform: translateX(-30%) skewX(-18deg);
	transition: transform .7s ease, opacity .35s ease;
}

/* Depth: top vignette + rich bottom scrim */
.xsStaff-card-vignette-shade
{
	position: absolute;
	inset: 0;
	z-index: 1;
	pointer-events: none;
	background:
		linear-gradient(180deg, fade(#000, 28%) 0%, transparent 32%),
		linear-gradient(180deg, transparent 38%, fade(#000, 35%) 68%, fade(#000, 78%) 100%),
		radial-gradient(120% 70% at 50% 100%, fade(#000, 45%), transparent 70%);
}

/* Inner frame rim */
.xsStaff-card-vignette-frame
{
	position: absolute;
	inset: 8px;
	z-index: 2;
	pointer-events: none;
	border-radius: calc(@xf-borderRadiusLarge - 2px);
	border: 1px solid fade(#fff, 18%);
	box-shadow: inset 0 0 0 1px fade(#000, 12%);
}

.xsStaff-card-vignette-top
{
	position: absolute;
	top: 12px;
	left: 12px;
	right: 12px;
	z-index: 4;
	display: flex;
	align-items: flex-start;
	justify-content: space-between;
	gap: 8px;
	pointer-events: none;
}
.xsStaff-card-vignette-topRight
{
	display: inline-flex;
	align-items: center;
	gap: 6px;
}

.xsStaff-card-vignette-meta
{
	position: absolute;
	left: 14px;
	right: 14px;
	bottom: 14px;
	z-index: 3;
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 4px;
	color: #fff;
	text-shadow: 0 2px 10px fade(#000, 45%);
}
.xsStaff-card-name
{
	display: block;
	max-width: 100%;
	font-size: 1.35rem;
	font-weight: @xf-fontWeightHeavy;
	line-height: 1.15;
	letter-spacing: -.02em;
	color: #fff;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.xsStaff-card-title
{
	display: inline-flex;
	align-items: center;
	margin-top: 2px;
	padding: 2px 8px;
	border-radius: 999px;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	color: #fff;
	background: fade(#000, 28%);
	border: 1px solid fade(#fff, 16%);
	backdrop-filter: blur(8px);
	-webkit-backdrop-filter: blur(8px);
	text-shadow: none;
}
.xsStaff-card-banners
{
	display: flex;
	flex-wrap: wrap;
	gap: 4px;
	margin-top: 4px;
}
.xsStaff-card-banners .userBanner
{
	box-shadow: 0 2px 8px fade(#000, 25%);
}
.xsStaff-card-hint
{
	display: inline-flex;
	align-items: center;
	gap: 6px;
	margin-top: 8px;
	padding: 5px 10px;
	border-radius: 999px;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
	color: #fff;
	letter-spacing: .02em;
	text-shadow: none;
	background: fade(#000, 32%);
	border: 1px solid fade(#fff, 18%);
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
}
.xsStaff-card-hint .fa,
.xsStaff-card-hint .fa--xf { font-size: 10px; opacity: .9; }

.xsStaff-card-badge
{
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 5px 10px;
	border-radius: 999px;
	background: fade(#000, 40%);
	border: 1px solid fade(#fff, 16%);
	color: #fff;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
	text-transform: uppercase;
	letter-spacing: .04em;
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
	box-shadow: 0 4px 14px fade(#000, 25%);
}
.xsStaff-card-badge .fa { font-size: 11px; color: var(--xsStaff-badge-color, #fff); }
.xsStaff-card-badge-img { width: 14px; height: 14px; border-radius: 3px; object-fit: cover; }
.xsStaff-card-badge-label { max-width: 120px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.xsStaff-card-statusdot
{
	width: 12px;
	height: 12px;
	border-radius: 50%;
	border: 2px solid #fff;
	box-shadow: 0 0 0 1px fade(#000, 25%), 0 2px 8px fade(#000, 35%);
}
.xsStaff-card-statusdot--online
{
	background: @xsStaff-online;
	box-shadow: 0 0 0 1px fade(#000, 25%), 0 0 0 4px fade(@xsStaff-online, 28%);
}
.xsStaff-card-statusdot--busy    { background: @xsStaff-busy; }
.xsStaff-card-statusdot--away    { background: @xsStaff-away; }
.xsStaff-card-statusdot--offline { background: fade(#fff, 55%); }

.xsStaff-card-medal
{
	display: inline-flex;
	align-items: center;
	gap: 4px;
	height: 24px;
	padding: 0 8px;
	border-radius: 999px;
	background: fade(#000, 40%);
	border: 1px solid fade(#fff, 16%);
	color: #fff;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
	box-shadow: 0 4px 14px fade(#000, 25%);
}
.xsStaff-card-medal .fa { font-size: 10px; color: #fbbf24; }

/* BACK — cinematic member dossier */
.xsStaff-card--back
{
	background: @xf-contentBg;
	overflow: hidden;
}
.xsStaff-card-back
{
	position: relative;
	display: flex;
	flex-direction: column;
	height: 100%;
	box-sizing: border-box;
	overflow: hidden;
}
.xsStaff-card-back-hero
{
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	height: 118px;
	overflow: hidden;
	pointer-events: none;
	z-index: 0;
}
.xsStaff-card-back-hero-media
{
	position: absolute;
	inset: -20% -10% auto;
	height: 160%;
	filter: blur(18px) saturate(1.15);
	transform: scale(1.12);
	opacity: .55;
}
.xsStaff-card-back-hero-media .avatar,
.xsStaff-card-back-hero-media .avatar img,
.xsStaff-card-back-hero-media a.avatar
{
	width: 100% !important;
	height: 100% !important;
	border-radius: 0 !important;
	object-fit: cover;
}
.xsStaff-card-back-hero-media .avatar > span
{
	width: 100% !important;
	height: 100% !important;
	border-radius: 0 !important;
	font-size: 4rem !important;
}
.xsStaff-card-back-hero-shade
{
	position: absolute;
	inset: 0;
	background:
		linear-gradient(180deg, fade(#000, 28%) 0%, fade(#000, 8%) 40%, @xf-contentBg 100%);
}
.xsStaff-card-back-hero-glow
{
	position: absolute;
	inset: auto -20% 20% -20%;
	height: 70%;
	background: radial-gradient(ellipse at center, fade(@xsStaff-accent, 28%) 0%, transparent 70%);
	opacity: .7;
}

.xsStaff-card-back-head
{
	position: relative;
	z-index: 1;
	display: flex;
	align-items: flex-end;
	gap: 12px;
	padding: 14px 14px 0;
	min-height: 96px;
}
.xsStaff-card-back-ava
{
	position: relative;
	flex: 0 0 auto;
	box-shadow: 0 10px 24px fade(#000, 22%);
	border-radius: @xf-borderRadiusLarge;
}
.xsStaff-card-back-ava .avatar,
.xsStaff-card-back-ava .avatar img
{
	width: 64px !important;
	height: 64px !important;
	border-radius: @xf-borderRadiusLarge !important;
	border: 2px solid @xf-contentBg !important;
	box-sizing: border-box;
}
.xsStaff-card-back-ava .xsStaff-card-statusdot
{
	position: absolute;
	right: 2px;
	bottom: 2px;
	width: 12px;
	height: 12px;
	border: 2px solid @xf-contentBg;
	box-shadow: none;
}
.xsStaff-card-back-id { min-width: 0; flex: 1; padding-bottom: 2px; }
.xsStaff-card-back-name
{
	display: block;
	font-size: 1.2rem;
	font-weight: @xf-fontWeightHeavy;
	line-height: 1.2;
	color: @xf-textColor;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.xsStaff-card-back-meta
{
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px;
	margin-top: 4px;
}
.xsStaff-card-back-title
{
	display: inline-flex;
	align-items: center;
	padding: 2px 8px;
	border-radius: 999px;
	background: @xf-contentBg;
	border: 1px solid @xsStaff-border;
	font-size: 11px;
	font-weight: @xf-fontWeightHeavy;
	color: @xf-textColorMuted;
	max-width: 100%;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.xsStaff-card-back-status
{
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 2px 8px;
	border-radius: 999px;
	font-size: 10px;
	font-weight: @xf-fontWeightHeavy;
	letter-spacing: .02em;
	text-transform: uppercase;
	background: @xf-contentBg;
	border: 1px solid @xsStaff-border;
	color: @xf-textColorMuted;
}
.xsStaff-card-back-status::before
{
	content: '';
	width: 6px;
	height: 6px;
	border-radius: 50%;
	background: currentColor;
}
.xsStaff-card-back-status--online { color: @xsStaff-online; }
.xsStaff-card-back-status--busy { color: @xsStaff-busy; }
.xsStaff-card-back-status--away { color: @xsStaff-away; }
.xsStaff-card-back-status--offline { color: @xf-textColorMuted; }
.xsStaff-card-back-banners
{
	display: flex;
	flex-wrap: wrap;
	gap: 4px;
	margin-top: 6px;
}
.xsStaff-card-back-banners .userBanner
{
	transform: scale(.88);
	transform-origin: left center;
}

.xsStaff-card-back-body
{
	position: relative;
	z-index: 1;
	display: flex;
	flex-direction: column;
	gap: 10px;
	flex: 1;
	min-height: 0;
	padding: 14px 14px 0;
	overflow: auto;
}

.xsStaff-card-stats
{
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 8px;
}
.xsStaff-card-stat
{
	position: relative;
	padding: 10px 10px 9px;
	border-radius: @xf-borderRadiusMedium;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	overflow: hidden;
}
.xsStaff-card-stat::after
{
	content: '';
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	height: 2px;
	background: linear-gradient(90deg, var(--xsStaff-accent, @xsStaff-accent), fade(@xsStaff-accent, 0%));
	opacity: .85;
}
.xsStaff-card-stat-value
{
	display: block;
	font-size: 1.15rem;
	font-weight: @xf-fontWeightHeavy;
	line-height: 1.15;
	color: @xf-textColor;
	font-variant-numeric: tabular-nums;
}
.xsStaff-card-stat-label
{
	display: block;
	margin-top: 2px;
	font-size: 10px;
	font-weight: @xf-fontWeightHeavy;
	letter-spacing: .04em;
	text-transform: uppercase;
	color: @xf-textColorMuted;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.xsStaff-card-since
{
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 10px;
	border-radius: @xf-borderRadiusMedium;
	background: @xf-contentAltBg;
	border: 1px dashed @xsStaff-border;
	font-size: @xf-fontSizeSmaller;
	color: @xf-textColorMuted;
}
.xsStaff-card-since-icon
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 26px;
	height: 26px;
	border-radius: 8px;
	background: fade(@xsStaff-accent, 12%);
	color: @xsStaff-accent;
	flex: 0 0 auto;
}
.xsStaff-card-since-text { min-width: 0; line-height: 1.3; }

.xsStaff-card-quote
{
	position: relative;
	margin: 0;
	padding: 12px 12px 12px 14px;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	border-radius: @xf-borderRadiusMedium;
	overflow: hidden;
}
.xsStaff-card-quote::before
{
	content: '';
	position: absolute;
	left: 0;
	top: 0;
	bottom: 0;
	width: 3px;
	background: var(--xsStaff-accent, @xsStaff-accent);
}
.xsStaff-card-quote p
{
	position: relative;
	z-index: 1;
	margin: 0;
	font-size: @xf-fontSizeSmall;
	line-height: @xf-lineHeightDefault;
	font-style: italic;
	color: @xf-textColor;
}
.xsStaff-card-quote-mark
{
	position: absolute;
	right: 8px;
	top: -6px;
	font-size: 48px;
	line-height: 1;
	font-family: Georgia, 'Times New Roman', serif;
	color: fade(@xsStaff-accent, 18%);
	pointer-events: none;
}

.xsStaff-card-bio
{
	padding: 10px 12px;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	border-radius: @xf-borderRadiusMedium;
	font-size: @xf-fontSizeSmall;
	line-height: @xf-lineHeightDefault;
}
.xsStaff-card-bio-content
{
	display: -webkit-box;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
	overflow: hidden;
}
.xsStaff-card-bio-content > * { margin: 0; }

.xsStaff-card-socials
{
	display: flex;
	flex-wrap: wrap;
	gap: 6px;
}
.xsStaff-card-social
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 32px;
	height: 32px;
	border-radius: 10px;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	color: @xf-textColorMuted;
	font-size: 13px;
	text-decoration: none;
	transition: transform .15s ease, background .15s ease, color .15s ease, border-color .15s ease;
}
.xsStaff-card-social:hover
{
	color: #fff;
	border-color: transparent;
	background: @xsStaff-accent;
	text-decoration: none;
	transform: translateY(-1px);
}
.xsStaff-card-social--discord:hover   { background: #5865F2; }
.xsStaff-card-social--twitter:hover   { background: #000; }
.xsStaff-card-social--twitch:hover    { background: #9146FF; }
.xsStaff-card-social--youtube:hover   { background: #FF0000; }
.xsStaff-card-social--instagram:hover { background: #E1306C; }
.xsStaff-card-social--github:hover    { background: #24292e; }
.xsStaff-card-social--website:hover   { background: @xsStaff-accent; }

.xsStaff-card-footer
{
	position: relative;
	z-index: 1;
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: 8px;
	margin-top: auto;
	padding: 12px 14px 14px;
	flex-wrap: wrap;
	border-top: 1px solid @xsStaff-border;
	background: @xf-contentBg;
}
.xsStaff-card-actions
{
	display: flex;
	gap: 6px;
	flex-wrap: wrap;
	flex: 1;
	min-width: 0;
}
.xsStaff-card-action
{
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 7px 10px;
	border-radius: 10px;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	color: @xf-textColor;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	text-decoration: none;
	white-space: nowrap;
	transition: background .15s ease, border-color .15s ease, transform .15s ease;
}
.xsStaff-card-action:hover
{
	background: fade(@xsStaff-accent, 10%);
	border-color: fade(@xsStaff-accent, 40%);
	color: @xf-textColor;
	text-decoration: none;
	transform: translateY(-1px);
}
.xsStaff-card-action--primary
{
	background: var(--xsStaff-accent, @xsStaff-accent);
	border-color: transparent;
	color: #fff !important;
	box-shadow: 0 6px 16px fade(@xsStaff-accent, 28%);
}
.xsStaff-card-action--primary:hover
{
	filter: brightness(1.06);
	color: #fff !important;
	background: var(--xsStaff-accent, @xsStaff-accent);
	border-color: transparent;
}
.xsStaff-card-action--pro
{
	background: @xf-contentBg !important;
	color: @xf-textColor !important;
	border-color: fade(@xsStaff-accent, 45%) !important;
}
.xsStaff-card-action--pro:hover
{
	background: fade(@xsStaff-accent, 10%) !important;
	color: @xf-textColor !important;
}

.xsStaff-card-thanks { margin: 0; }
.xsStaff-card-thanks-btn
{
	display: inline-flex;
	align-items: center;
	gap: 6px;
	padding: 7px 11px;
	border-radius: 999px;
	background: fade(@xsStaff-busy, 10%);
	border: 1px solid fade(@xsStaff-busy, 28%);
	color: @xsStaff-busy;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	cursor: pointer;
	font-variant-numeric: tabular-nums;
	box-shadow: 0 4px 12px fade(@xsStaff-busy, 12%);
	transition: background .15s ease, color .15s ease, transform .15s ease;
}
.xsStaff-card-thanks-btn:hover:not(:disabled)
{
	background: @xsStaff-busy;
	border-color: transparent;
	color: #fff;
	transform: translateY(-1px);
}
.xsStaff-card-thanks-btn.is-thanked
{
	background: @xsStaff-busy;
	border-color: transparent;
	color: #fff;
	pointer-events: none;
}
.xsStaff-card-thanks-btn.is-thanked .xsStaff-card-thanks-heart { animation: xsStaff-heartbeat .55s ease; }
@keyframes xsStaff-heartbeat
{
	0% { transform: scale(1); }
	30% { transform: scale(1.35); }
	100% { transform: scale(1); }
}
.xsStaff-card-thanks-btn--disabled
{
	background: @xf-contentAltBg;
	border-color: @xsStaff-border;
	color: @xf-textColorMuted;
	cursor: default;
	box-shadow: none;
}
.xsStaff-card--justThanked { box-shadow: 0 0 0 2px fade(@xsStaff-accent, 35%); }

.xsStaff-empty
{
	padding: 40px 24px;
	text-align: center;
	background: @xf-contentBg;
	border: 1px dashed @xsStaff-border;
	border-radius: @xf-borderRadiusLarge;
}
.xsStaff-empty-icon
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 48px;
	height: 48px;
	margin-bottom: 10px;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentAltBg;
	color: @xf-textColorMuted;
	font-size: 20px;
}
.xsStaff-empty-text { color: @xf-textColorMuted; }

.xsStaff-reveal
{
	opacity: 0;
	transform: translateY(10px);
	transition: opacity .35s ease, transform .35s ease;
	transition-delay: var(--xs-reveal-delay, 0ms);
}
.xsStaff-reveal--in { opacity: 1; transform: none; }

/* Legacy unused */
.xsStaff-card-aura,
.xsStaff-card-spotlight,
.xsStaff-card-head,
.xsStaff-tilt { display: none; }

/* Widget */
.xsStaffWidget { padding: 4px 0; }
.xsStaffWidget--compact { display: flex; flex-wrap: wrap; gap: 8px; padding: 8px; }
.xsStaffWidget-compactAvatar:hover { transform: scale(1.05); }
.xsStaffWidget--grid
{
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
	gap: 8px;
	padding: 8px;
}
.xsStaffWidget-mini
{
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 5px;
	padding: 8px 4px;
	border-radius: @xf-borderRadiusMedium;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	text-decoration: none;
	color: @xf-textColor;
}
.xsStaffWidget-mini:hover
{
	background: fade(@xsStaff-accent, 8%);
	border-color: fade(@xsStaff-accent, 35%);
	text-decoration: none;
	color: @xf-textColor;
}
.xsStaffWidget-mini-name
{
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	max-width: 100%;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}
.xsStaffWidget-mini-title { font-size: @xf-fontSizeSmallest; color: @xf-textColorMuted; }

.xsStaffWidget--spotlight
{
	padding: @xf-paddingLarge;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
	display: flex;
	gap: 12px;
	align-items: center;
}
.xsStaffWidget--spotlight::before { content: none; }
.xsStaffWidget-spotlight-avatar .avatar,
.xsStaffWidget-spotlight-avatar .avatar img
{
	width: 56px !important;
	height: 56px !important;
}
.xsStaffWidget-spotlight-name
{
	display: block;
	font-weight: @xf-fontWeightHeavy;
	color: @xf-textColor;
}
.xsStaffWidget-spotlight-title
{
	display: block;
	font-size: @xf-fontSizeSmaller;
	color: @xf-textColorMuted;
	margin-top: 2px;
}
.xsStaffWidget-spotlight-quote
{
	margin: 6px 0 0;
	font-size: @xf-fontSizeSmall;
	color: @xf-textColorMuted;
	font-style: italic;
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
}
.xsStaffWidget-viewAll
{
	display: block;
	margin: 8px;
	padding: 8px 10px;
	text-align: center;
	border-radius: @xf-borderRadiusMedium;
	background: @xsStaff-accent;
	color: #fff;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	text-decoration: none;
}
.xsStaffWidget-viewAll:hover { color: #fff; text-decoration: none; filter: brightness(1.05); }

/* Secondary pages */
.xsStaff-proPage { margin-bottom: @xf-elementSpacer; }
.xsStaff-proPage-hero
{
	padding: @xf-paddingLarge;
	margin-bottom: @xf-paddingLarge;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentBg;
	border: 1px solid @xsStaff-border;
}
.xsStaff-proPage-hero-eyebrow
{
	display: inline-flex;
	align-items: center;
	gap: 6px;
	margin-bottom: 6px;
	color: @xf-textColorMuted;
	font-size: @xf-fontSizeSmaller;
	font-weight: @xf-fontWeightHeavy;
	text-transform: uppercase;
}
.xsStaff-proPage-hero-eyebrow .fa { color: @xsStaff-accent; }
.xsStaff-proPage-hero-title
{
	margin: 0 0 4px;
	font-size: @xf-fontSizeLarger;
	font-weight: @xf-fontWeightHeavy;
}
.xsStaff-proPage-hero-subtitle
{
	margin: 0;
	color: @xf-textColorMuted;
}
.xsStaff-statGrid
{
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
	gap: @xf-paddingMedium;
}
.xsStaff-statBox
{
	padding: @xf-paddingLarge;
	border-radius: @xf-borderRadiusLarge;
	background: @xf-contentAltBg;
	border: 1px solid @xsStaff-border;
}
.xsStaff-statBox-num
{
	font-size: @xf-fontSizeLarger;
	font-weight: @xf-fontWeightHeavy;
	font-variant-numeric: tabular-nums;
}
.xsStaff-statBox-label
{
	margin-top: 4px;
	font-size: @xf-fontSizeSmallest;
	font-weight: @xf-fontWeightHeavy;
	text-transform: uppercase;
	color: @xf-textColorMuted;
}
.xsStaff-chart-empty
{
	padding: 32px 20px;
	text-align: center;
	color: @xf-textColorMuted;
}
.xsStaff-chart-empty .fa { display: block; font-size: 28px; margin-bottom: 8px; opacity: .45; }
.xsStaff-chart-axis { stroke: @xsStaff-border; stroke-width: 1; }
.xsStaff-proPage .block { margin-bottom: 0; }
.xsStaff-proPage .block-container
{
	border-radius: @xf-borderRadiusLarge;
	border: 1px solid @xsStaff-border;
	background: @xf-contentBg;
	overflow: hidden;
}
.xsStaff-proPage .block-header { display: none; }

@media (max-width: 900px)
{
	.xsStaff-masthead-stage
	{
		grid-template-columns: 1fr;
		padding: 24px 20px 12px;
		gap: 8px;
	}
	.xsStaff-masthead-roster { min-height: 180px; }
	.xsStaff-masthead-faces { width: 200px; height: 180px; }
	.xsStaff-masthead-face--lead .avatar,
	.xsStaff-masthead-face--lead .avatar img
	{
		width: 96px !important;
		height: 96px !important;
	}
	.xsStaff-masthead-watermark { opacity: .04; right: 0; }
	.xsStaff-masthead-dock { margin: 0 12px 12px; }
}

@media (max-width: 700px)
{
	.xsStaff-masthead { --xsStaff-mast-pad: 18px; }
	.xsStaff-masthead-dock { grid-template-columns: 1fr 1fr; gap: 8px; }
	.xsStaff-masthead-stat { padding: 12px; border-radius: 14px; }
	.xsStaff-masthead-stat-num { font-size: 1.25rem; }
	.xsStaff-masthead-stat-icon { width: 36px; height: 36px; border-radius: 11px; }
	.xsStaff-masthead-face .avatar,
	.xsStaff-masthead-face .avatar img
	{
		width: 46px !important;
		height: 46px !important;
	}
	.xsStaff-masthead-faceMore { width: 42px; height: 42px; }

	.xsStaff-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
	.xsStaff-flip { height: 320px; }
	.xsStaff-card-name { font-size: 1.15rem; }
	.xsStaff-card-vignette-frame { inset: 6px; }
	.xsStaff-card-action:not(.xsStaff-card-action--primary) span { display: none; }
	.xsStaff-card-action:not(.xsStaff-card-action--primary)
	{
		width: 34px;
		height: 34px;
		padding: 0;
		justify-content: center;
	}
	.xsStaff-card-back-ava .avatar,
	.xsStaff-card-back-ava .avatar img
	{
		width: 56px !important;
		height: 56px !important;
	}
	.xsStaff-card-stats { gap: 6px; }
	.xsStaff-card-stat { padding: 8px; }
	.xsStaff-card-stat-value { font-size: 1.05rem; }
}

@media (prefers-reduced-motion: reduce)
{
	.xsStaff-flip-inner,
	.xsStaff-card-vignette-media,
	.xsStaff-card-vignette-sheen { transition: none !important; }
	.xsStaff-flip:hover .xsStaff-card-vignette-media { transform: none; }
	.xsStaff-reveal { opacity: 1 !important; transform: none !important; transition: none !important; }
	.xsStaff-card-thanks-btn.is-thanked .xsStaff-card-thanks-heart { animation: none; }
	.xsStaff-masthead-sheen,
	.xsStaff-masthead-pulse,
	.xsStaff-masthead-eyebrow-dot,
	.xsStaff-masthead-orb--a,
	.xsStaff-masthead-orb--b,
	.xsStaff-masthead-ring,
	.xsStaff-masthead-face { animation: none !important; }
}
